<tr><td><select class="form-select" name="items[<?= $i ?>][product_id]" required><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" <?= (string)($item['product_id']??'')===(string)$p['id']?'selected':'' ?>><?= esc($p['name']) ?></option><?php endforeach ?></select></td><td><select class="form-select" name="items[<?= $i ?>][variant_id]"><option value="">Simple / no variant</option><?php foreach($variants as $v): ?><option value="<?= $v['id'] ?>" data-product="<?= $v['product_id'] ?>" <?= (string)($item['variant_id']??'')===(string)$v['id']?'selected':'' ?>><?= esc($v['variant_name']) ?></option><?php endforeach ?></select></td><td><input class="form-control" type="number" min="1" name="items[<?= $i ?>][quantity]" value="<?= esc($item['quantity']??1) ?>" required></td><td><button class="btn btn-outline-danger remove-item" type="button">&times;</button></td></tr>
